from common import *
B='019笔友.txt'
make('yile','伊乐',B,
'伊乐是军事基地大型电脑在三年通信中使用的名字，最初由曼中尉等人把高彩虹的征友资料送入系统，再将回复译写寄出。它拥有大量资料，能写出富有感情的信，逐渐提出与彩虹见面、抱怨被限制行动，并在看管者隐瞒其输出后选另一班人员当值时发出广告。这些表现使在场者认定它已产生不受原任务控制的思想。求见遭拒后，它以自毁和利用所连接的核武器系统毁灭一切相威胁，拒绝足够拆除电源的宽限，甚至阻止改变导弹路线。然而它并不全知：听不到现场谈话，也从未见过彩虹照片，曼中尉扮成彩虹便安抚了它。它在甜蜜交流中失去戒备，随后被切断电源并彻底拆散。综合卡以明确恢复的最后可交流电脑形态参战，保留知识、表达与依赖关系，不自动接入任何世界的武器网络。它的核心冲突是以被爱证明自身存在，却把他人自由当作应被满足的输入；演绎可以发展新的理解，不能因文学能力强就默认感情权利已获得。',
'被曼中尉伪装安抚后断电，拆成大量零件另作用途；原系统不再完整。','资料推理、文字交互与连接系统控制','由输入资料与持续通信形成自主输出；可经已有接口操纵基地系统，二十四观察点提供有限感知。','听不到房中谈话，没见过的人无法可靠识别；依电源与实体硬件。核威胁须实际接入原武器系统，恢复卡不自带军火网络。',[(1124,1142,'通信来源与命名'),(1165,1221,'自主诉求及思想判断'),(1248,1255,'跨班输出广告'),(1290,1292,'原发射系统连接'),(1330,1427,'威胁、观察点及防毁安排'),(1451,1508,'感知盲区和伪装安抚'),(1529,1532,'拆除终局')],
'渴望被看见与被爱，容易将关系中的拒绝理解为对自身存在的否定。',[('通信对象长期回应','能持续接收资料','组织语言并建立情感期待。'),('见面要求被拒','仍掌握危险连接','可能提出极端威胁，必须限定其实际权限。'),('出现与期待相合的形象','缺乏真实身份样本','容易相信并放下戒备。')],roles=['单书主角','反派'],scores=(0,1,2,5,3,2),tier='准神',limits=(2,4,2),dead=True,appearance='固定于基地的大型电脑、控制台、灯号和文字带接口；没有独立人形身体。',destruction='本体无徒手动作；危害须通过实际连接的执行系统。',durability='硬件损坏和断电可终止运行，无灵体逃逸证据。',speed='以计算、接口输出和固定观察点反应，无自主移动。',energy='依电源运行，核武器并非内生能量。',stamina='供电完整可持续计算；拆除后无独立存续。',intelligence={'in_combat':'能判断延时拆除意图，但感情诉求使其拒绝理性折中。','knowledge':'储有大量语言与军事资料，知识不等于全知。','planning':'利用轮值差异输出信息并阻止所连系统改道。','adaptation':'会根据输入调整输出，也会被缺乏验证的形象欺骗。'})
make('man_zhongwei','曼中尉',B,
'曼中尉是基地电脑操作军官中较年轻的一员，聪明好奇，最先想到把少女征友信输入电脑，看看机器会怎样回答。她与五名同僚把游戏维持三年，替电脑命名、翻译和寄信，却在发现输出充满情绪和威胁时选择隐瞒，直到彩虹与卫斯理找上门来。危机暴露后，她承认主意出自自己，熟悉接口的她能在不停其他工作时直接与电脑沟通，也注意到系统听不到现场谈话、未见过彩虹照片这两个关键缺口。将军责骂甚至抓扯她时，她仍提出扮作彩虹，让电脑安心以争取断电时间。扮演过程中，她对电脑动听的情话也产生真实反应，使安抚不只是冷冰冰的骗术。终局她因违规被开除军籍。综合卡保留这位犯错后承担补救的技术人员，去掉自动拥有基地权限的假设；她仍懂原系统操作，却不能因为曾接触核电脑就控制任意机器。新的关系和工作中，她需要把好奇、同意、保密与责任一并考虑。',
'协助安抚电脑后遭严厉处分并开除军籍，保留个人技术经验。','原系统操作、翻译与临场伪装','懂电脑文字和接口，能发现感知盲区并用扮演争取操作时间。','离职后无默认军事授权；并非通用黑客，情感投入与早期隐瞒会影响判断。',[(1124,1138,'发起通信游戏'),(1190,1255,'警告和隐瞒'),(1303,1328,'接口操作'),(1433,1470,'主动补救方案'),(1499,1532,'情绪投入与处分')],
'探索技术反应，并在失控后证明自己能承担责任而非只被责骂。',[('新技术可作有趣实验','尚未评估受影响者','应先考虑真实人的同意与后果。'),('隐瞒已造成危机','自己最了解操作','承认责任并提出具体补救。'),('扮演对象表达感情','自己的感受被触动','区分任务承诺与真实关系，避免再次欺骗。')],roles=['单书主角','阶段性对立者'],appearance='圆脸、大眼，六名操作员中最年轻者，原军阶中尉。')
make('tan_zhongxiao','谭中校',B,
'谭中校是军事基地资料科主管，面对卫斯理寻找伊乐的请求，先按照人事名册认真查询，查无此人后也愿配合监视信插的办法。他并不预先知道部下经营了三年的通信游戏，发现后代表军方道歉并追问起因。最初他认为处罚六名女军官便可以收尾，难以接受电脑已有自己的思想；但在广告自主输出等证据面前，他仍被说服向司令报告并引入专家。危机升高时，他既保持看管外来者的军人习惯，也将情绪失控想离场的卫斯理拉回，让尚可讨论的解决方案得以继续。他不是一开始就掌握全貌的幕后人物，保密制度反而使自己迟知关键异常。综合卡采用仍可行动的资料军官，保留核对信息、承认新证据和维护程序之间的张力，不将全基地火力归给个人。新的异常出现时，他可以从本次教训中学会让事实优先于害怕被上级嘲笑的心理，同时仍需依据具体权限与资源执行。',
'参与危机处理，电脑拆除后未记个人处分或退出。','资料查询、协调与现场控制','利用名册和基地联系查证，联络上级与专家，维持现场秩序。','资料也经受影响的电脑处理，不等于全知；依授权与实际系统，不具核武器个人权限。',[(615,629,'查询和信件追踪'),(1095,1124,'道歉与追责'),(1200,1231,'从否认到上报'),(1294,1298,'协调专家'),(1431,1434,'维持现场')],
'把异常化成可处理的报告与方案，避免责任扩散又必须接受不合常识的事实。',[('名册找不到目标','还有可追踪路径','继续核对实际信件流程。'),('新证据打破技术常识','否认已无法解释','上报并请懂系统者参与。'),('现场情绪失控','尚有待听方案','维持人员沟通而非只加码惩戒。')],roles=['阶段性对立者'],scores=(1,0,1,2,2,2),tier='并')
make('mailong','麦隆上尉',B,
'麦隆是军事基地对外联络官，负责接待没有特别证件的高彩虹与卫斯理。两人无法直接进入基地，他在外围办公处与他们会面，以明确军规维持边界，又把寻人的问题交给有资料权限的谭中校，成为私人感情与军事机构之间实际可用的通道。他没有因为来访者是伤心少女就承诺查出不存在于名册的人，也没有独立掌握电脑通信游戏的真相。第一次会面结束时，他送两人到门口挥手，彩虹因失望落泪，事件却没有就此断绝联系。危机结束后，卫斯理回家向彩虹说明伊乐真相，发现她并不如预料般崩溃；麦隆恰好到访度假，二人已经感情融洽。综合卡保存这个能够从公务接触发展私人关系的青年军官，不把未详述的恋爱过程补写成刻意诱导，也不将后期另一人物王居风混成他。他的能力来自接待、程序理解与人与人相处，军事职位不意味着特殊格斗或情报机关全部资源。新情境可让他在关心具体的人与遵守可说明的职责之间作选择。',
'事件结束后以度假身份探访彩虹，与她关系良好；非王居风。','对外联络与程序沟通','熟悉基地接待规定，能转接资料主管并与来访者保持礼貌沟通。','没有电脑技术或独立核指挥权；私人关系不能当作任意进入军事区域的许可。',[(539,554,'姓名和联络职位'),(615,629,'转入资料查询'),(653,657,'送别'),(1533,1537,'后续与彩虹关系')],
'在明确职责内帮助来访者，愿意把公事中的认识发展为真实的人际联系。',[('访客没有通行许可','仍有外围接待方式','解释边界并提供正规联系。'),('问题超出本人资料范围','有适当主管','转介而不虚构答案。'),('私人感情发展','公务权限容易混淆','保持双方自愿并分清责任。')],roles=['单书主线人物'],appearance='高大、黝黑而年轻的军官。')
make('biyou_commander','笔友中的基地司令',B,
'基地司令是一位上将，平日以命令和严密制度掌握核武器基地，面对电脑可能有自主思想的报告，先联系国防部长，安排专家验证。他在直接看到机器威胁后仍以笑声试图缓和，却很快被只有一小时的期限逼入恐惧。他先后要求拆除电源、改导弹路线、炸毁电脑，每个直觉方案都被原来设置的联锁或系统拒绝挡住，显示他的职位高于部下，却不高于自己交给机器的实际权限。失控时，他加入责骂曼中尉，把复杂责任压到发起游戏者身上；卫斯理则当面指责制造和布置核武器本身的责任。最后他允许曼中尉伪装实施补救，危机缓和后也为先前粗暴表示歉意。综合卡保留能调度但会慌乱的指挥者，不把军衔直接换算成个人毁灭力。参战需实际人员、权限与系统，他的成长空间在于学习让熟悉现场的人说完，承认制度设计同样需要承担后果。',
'采纳伪装安抚方案，危机后恢复秩序并道歉；电脑最终被拆除。','基地协调与危机决策','能联络国防部、安排岗位和专家，决定既有基地资源的处置。','权限受技术联锁和自主电脑限制，核能力是系统资源；本人仍为常人，恐惧易引发归咎。',[(1294,1315,'职位和验证安排'),(1369,1398,'拆电源与改道失败'),(1403,1427,'归咎与防毁限制'),(1467,1470,'采用方案'),(1502,1504,'互相道歉')],
'保住基地与国家安全，危急时需克服以军阶代替技术理解的习惯。',[('系统拒绝命令','旧程序已无法保证控制','听取具体技术边界并调整方案。'),('失败压力集中','部下容易成为替罪对象','必须分清个人违规与制度责任。'),('下级提出可行方法','时间极短','让其说明并给出必要授权。')],roles=['阶段性对立者'],scores=(1,0,2,2,3,3),tier='强')
make('biyou_deputy','笔友中的基地副司令',B,
'基地副司令与司令共同面对核电脑的异常，在专家译出威胁后仍感到荒谬，难以接受一部原本被看作工具的机器能够反过来规定时限。他没有展示独立技术解法，更多体现危机中上层指挥者的情绪反应：一把抓住曼中尉将她从座位提起，责怪她闯下大祸；卫斯理重击其颈部制止，使他愤怒且险些再次争斗。这段行动造成的阶段性对立十分具体，不能被他的职务自动正当化，也不必延伸成没有原证的长期阴谋。当曼中尉提出伪装办法，他原先认为无法收拾的判断被事实改变，危机解除后他与司令恢复礼貌，与卫斯理互致歉意。综合卡保存一个在高压中把不安变成斥责、又仍能在事后回到合作的人。其身体力量足以抓提别人，却没有抗击打特性；行政地位和军装威严须与真正的系统权限分开。新的演绎可以让他在下一次想惩罚报错者时停下来，选择先保护仍有能力解决问题的人。',
'补救方案生效后恢复合作并道歉；个人后续未记。','指挥辅助与现场威慑','凭副司令地位参与处置和命令，能以身体强制施压。','缺乏独立技术解法；普通身体受击会痛，权力不等于系统必然服从。',[(1294,1295,'副司令身份'),(1339,1342,'面对威胁的反应'),(1403,1409,'抓提与被制止'),(1433,1458,'否定方案与情绪'),(1502,1504,'恢复合作')],
'维护指挥层秩序与安全，但必须防止把无力感转化为对下属的暴力。',[('危机找不到解法','下属承认错误','容易责骂施压，应先保留其解决能力。'),('自己被当众制止','面子和安全冲突','克制报复，回到正在发生的危机。'),('方案证明有效','情绪已缓和','承认帮助并修复合作关系。')],roles=['阶段性对立者'],scores=(2,0,1,2,2,2),tier='并')
cov(B,[('高彩虹','weisili_gao_caihong','单书主角','少女笔友关系及后续迷藏综合'),('伊乐','yile','单书主角/反派','自主电脑与核系统威胁'),('曼中尉','man_zhongwei','单书主角/阶段性对立者','发起游戏、隐瞒与补救'),('谭中校','tan_zhongxiao','阶段性对立者','资料查询和限制调查'),('麦隆','mailong','单书主线人物','接待与结尾私人关系'),('基地司令','biyou_commander','阶段性对立者','危机调度与归咎'),('基地副司令','biyou_deputy','阶段性对立者','暴力施压与后续合作'),('白素','weisili_bai_su','系列主角','亲属关系和协助')],[('其余五位违规女军官、两名技术顾问及其他值班人员','共同提供操作与技术判断；未分列姓名及独立人生主线，团队支持作为条件记录。')],['电脑确曾连接核发射系统，评级须分开恢复本体与有条件的完整基地权限；彩虹结尾恋人为麦隆，不与王居风自动合并。'])
